end
function Core.scope()
    local self={changes={},order={},cleanup={},callbacks={},closed=false}
    function self:defer(fn) self.cleanup[#self.cleanup+1]=fn end
    function self:attribute(object,key,value)
        self.attributes=self.attributes or {}
