        local mover=Instance.new("LinearVelocity"); mover.Attachment0=attachment; mover.RelativeTo=Enum.ActuatorRelativeTo.World; mover.MaxForce=math.huge; mover.VectorVelocity=Vector3.zero; mover.Parent=part
        scope:defer(function() mover:Destroy() end); return {part=part,mover=mover}
    end,step=function(_,state,s)
        assert(state.part.Parent,"Character removed")
        local camera=camera_service(); local vector=Vector3.zero
        if not input:GetFocusedTextBox() then
            if input:IsKeyDown(Enum.KeyCode.W) then vector=vector+camera.CFrame.LookVector end
            if input:IsKeyDown(Enum.KeyCode.S) then vector=vector-camera.CFrame.LookVector end
            if input:IsKeyDown(Enum.KeyCode.D) then vector=vector+camera.CFrame.RightVector end
            if input:IsKeyDown(Enum.KeyCode.A) then vector=vector-camera.CFrame.RightVector end
            if input:IsKeyDown(Enum.KeyCode.Space) then vector=vector+Vector3.yAxis end
            if input:IsKeyDown(Enum.KeyCode.Q) then vector=vector-Vector3.yAxis end
        end
        state.mover.VectorVelocity=vector.Magnitude>0 and vector.Unit*s.fly_speed or Vector3.zero
    end,conflicts={"spin","guard"}})
    local basket_index={parts={},ready=false,links={},last_scan=-10,scans=0}
    local function possible_rim(object)
        if not object:IsA("BasePart") then return false end
        local name=object.Name:lower():gsub("[^%w]","")
        return name=="rim" or name=="basketrim" or name=="hooprim" or name=="ring"
    end
    local function valid_rim(object)
        if not object.Parent or not object:IsDescendantOf(workspace) or not possible_rim(object) then return false end
        local ring=object.Name:lower():gsub("[^%w]","")=="ring"
        local ancestor=object.Parent; local hoop_context=false
        while ancestor and ancestor~=workspace do
            local key=ancestor.Name:lower()
            if key=="characters" or key=="basketballs" or key:sub(1,5)=="pivot" or ancestor:IsA("Camera") then return false end
            if ring and (key:find("hoop",1,true) or key:find("basket",1,true) or key:find("goal",1,true)) then hoop_context=true end
            ancestor=ancestor.Parent
        end
        return not ring or hoop_context
    end
    local function seed_rims()
        basket_index.parts={}; basket_index.scans=basket_index.scans+1; basket_index.last_scan=os.clock()
        for _,object in ipairs(workspace:GetDescendants()) do if possible_rim(object) then basket_index.parts[object]=true end end
    end
    local function indexed_rims()
        if not basket_index.ready then
            basket_index.ready=true
            local added,removed=workspace.DescendantAdded,workspace.DescendantRemoving
            basket_index.streaming=added and removed and type(added.Connect)=="function" and type(removed.Connect)=="function"
            if basket_index.streaming then
                basket_index.links[1]=added:Connect(function(object) if possible_rim(object) then basket_index.parts[object]=true end end)
                basket_index.links[2]=removed:Connect(function(object) basket_index.parts[object]=nil end)
            end
            seed_rims()
        elseif not basket_index.streaming and os.clock()-basket_index.last_scan>=1 then
            -- Compatibility fallback only when descendant events are unavailable.
            seed_rims()
        end
        local result={}
        for object in pairs(basket_index.parts) do
            if not object.Parent or not object:IsDescendantOf(workspace) then basket_index.parts[object]=nil
            elseif valid_rim(object) then result[#result+1]={object=object,label="Rim"} end
        end
        return result
    end
    function Engine:close_rim_index()
        for _,link in ipairs(basket_index.links) do link:Disconnect() end
        basket_index.links={}; basket_index.parts={}; basket_index.ready=false
    end
    Engine.rim_lookup_stats=basket_index
    local function candidates(kind)
        local list={}
        if kind=="players" then
            for _,who in ipairs(players:GetPlayers()) do if who~=ctx.player then local model=rig(who); if model then list[#list+1]={object=model,label=who.DisplayName or who.Name,who=who} end end end
        elseif kind=="balls" then
            local folder=workspace:FindFirstChild("Basketballs")
            if folder then for _,obj in ipairs(folder:GetChildren()) do if obj:IsA("BasePart") then list[#list+1]={object=obj,label="Ball"} end end end
        elseif kind=="rims" then
            list=indexed_rims()
        end
        return list
    end
    local function position(obj)
        if obj:IsA("BasePart") then return obj.Position,obj end
        local part=obj:FindFirstChild("HumanoidRootPart") or obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")
        return part and part.Position,part
    end
    local function esp(id,title,kind,names)
        local function update(scope,state,s)
            local seen={}; local origin=camera_service().CFrame.Position; local count=0
            for _,item in ipairs(candidates(kind)) do
                local point,part=position(item.object)
                local local_rig=rig(); local team=local_rig and local_rig:GetAttribute("Team")
                local other_team=kind=="players" and item.object:GetAttribute("Team")
                local teammate=s.team_check and team and team~=0 and other_team==team
                if point and part and not teammate and (point-origin).Magnitude<=s.esp_distance and count<20 then
                    count=count+1; seen[item.object]=true
                    local visual=state.items[item.object]
                    if not visual then
                        if names then
                            local billboard=Instance.new("BillboardGui"); billboard.Adornee=part; billboard.AlwaysOnTop=true; billboard.Size=UDim2.fromOffset(180,26); billboard.StudsOffset=Vector3.new(0,3,0); billboard.Parent=state.folder
                            local text=Instance.new("TextLabel"); text.BackgroundTransparency=1; text.Size=UDim2.fromScale(1,1); text.TextColor3=Color3.fromRGB(215,195,232); text.TextSize=14; text.Font=Enum.Font.BuilderSans; text.TextStrokeTransparency=.4; text.Parent=billboard
                            visual={object=billboard,text=text}; state.items[item.object]=visual
                        else
                            local highlight=Instance.new("Highlight"); highlight.Adornee=item.object; highlight.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop; highlight.FillColor=Color3.fromRGB(164,132,190); highlight.OutlineColor=Color3.fromRGB(215,195,232); highlight.FillTransparency=.7; highlight.Parent=state.folder
                            visual={object=highlight}; state.items[item.object]=visual
                        end
                    end
                    if visual.text then visual.text.Text=item.label.." / "..math.floor((point-origin).Magnitude).." studs" end
                end
            end
            for obj,visual in pairs(state.items) do if not seen[obj] then visual.object:Destroy(); state.items[obj]=nil end end
        end
        add(id,title,"Visuals","Distance-limited local overlays; maximum 20 objects",{start=function(scope,s)
            local folder=Instance.new("Folder"); folder.Name="Pivot_"..id; folder.Parent=workspace; scope:defer(function() folder:Destroy() end)
            local state={folder=folder,items={}}; update(scope,state,s); return state
        end,step=update,interval=.25})
    end
    esp("player_esp","Player highlights","players",false)
    esp("player_names","Player names / distances","players",true)
    esp("ball_esp","Ball highlights","balls",false)
    esp("ball_names","Ball distances","balls",true)
    esp("rim_esp","Rim highlights","rims",false)
    local function line(parent)
        local object=Instance.new("Frame"); object.BorderSizePixel=0; object.BackgroundColor3=Color3.fromRGB(193,166,213); object.AnchorPoint=Vector2.new(0,.5); object.Parent=parent; return object
    end
    local function draw_line(object,a,b)
        local d=b-a; object.Position=UDim2.fromOffset(a.X,a.Y); object.Size=UDim2.fromOffset(d.Magnitude,1); object.Rotation=math.deg(math.atan2(d.Y,d.X)); object.Visible=true
    end
    local function nearest_rim(origin)
        local best,distance
        for _,item in ipairs(candidates("rims")) do local d=(item.object.Position-origin).Magnitude; if not distance or d<distance then best=item.object; distance=d end end
        return best,distance
    end
    function Engine:select_defensive_rim()
        local part=assert(root(),"Enter a court first"); self.defensive_rim=assert(nearest_rim(part.Position),"No map rim found")
        ctx.report("Selected nearest rim as defensive goal")
    end
    local function selected_target(s)
        if s.guard_target=="" then
            local mine=assert(root(),"Local root unavailable"); local team=rig():GetAttribute("Team"); local best,best_part,distance
            for _,who in ipairs(players:GetPlayers()) do
                if who~=ctx.player then
                    local model=rig(who); local part=root(who)
                    local teammate=s.team_check and team and team~=0 and model and model:GetAttribute("Team")==team
                    if model and part and not teammate and (not s.ball_handler_only or held_ball(model) or model:GetAttribute("Basketball")==true) then
                        local d=(part.Position-mine.Position).Magnitude
                        if not distance or d<distance then best=model; best_part=part; distance=d end
                    end
                end
            end
            assert(best,"No eligible opponent nearby"); return best,best_part
        end
        local matches={}
        for _,who in ipairs(players:GetPlayers()) do if who~=ctx.player and who.Name:lower():sub(1,#s.guard_target)==s.guard_target:lower() then matches[#matches+1]=who end end
        assert(#matches==1,"Defense target must match one other player")
        local model=assert(rig(matches[1]),"Target rig unavailable")
        return model,assert(root(matches[1]),"Target root unavailable")
    end
    local function jump_key(s) assert(s.jump_key=="Space" or s.jump_key:match("^[A-Z]$"),"Jump key must be Space or A-Z"); return s.jump_key end
    local function pulse(scope,state,key)
        if ctx.runner.current or input:GetFocusedTextBox() or state.pulse then return end
        hold(scope,key,true); state.pulse=key; state.release_at=os.clock()+.06
    end
    local function finish_pulse(scope,state)
        if state.pulse and os.clock()>=state.release_at then hold(scope,state.pulse,false); state.pulse=nil end
    end
    Engine.settings.guard_contest=true
    Engine.settings.guard_close_front=true
    function Core.guard_choose(list,origin,previous,hold_previous)
        local best,distance,retained,has_handler
        for _,item in ipairs(list) do if item.has_ball then has_handler=true; break end end
        for _,item in ipairs(list) do if not has_handler or item.has_ball then
            local d=(item.position-origin).Magnitude
            if not distance or d<distance then best=item; distance=d end
            if item.key==previous then retained=item end
        end end
        if retained and (not has_handler and hold_previous or (retained.position-origin).Magnitude<=distance+3) then return retained end
        return best
    end
    function Core.guard_observe(tracker,position,reported,now)
        local flat=function(v) return Vector3.new(v.X,0,v.Z) end
        local old=tracker.sample; local velocity=tracker.velocity or Vector3.zero
        local physical=reported and flat(reported) or Vector3.zero
        if physical.Magnitude>40 then physical=physical.Unit*40 end
        if not old or now-old.time>.5 then velocity=physical; tracker.sample={position=position,time=now}
        elseif now-old.time>=.008 and ((position-old.position).Magnitude>.025 or now-old.time>=.075) then
            local observed=flat(position-old.position)/(now-old.time)
            if observed.Magnitude>65 then
                velocity=Vector3.zero; tracker.reversed_until=now+.18
            else
                local reversed=velocity.Magnitude>4 and observed.Magnitude>4 and velocity:Dot(observed)<0
                if reversed then tracker.reversed_until=now+.18 end
                -- Replicated physical velocity can still point along the previous dribble.
                velocity=physical.Magnitude>.1 and observed.Magnitude>.1 and physical:Dot(observed)>0 and observed*.8+physical*.2 or observed
                if velocity.Magnitude>40 then velocity=velocity.Unit*40 end
            end
            tracker.sample={position=position,time=now}
        end
        tracker.velocity=velocity
        return velocity,now<(tracker.reversed_until or 0)
    end
    function Core.guard_wide_waypoint(origin,handler,basket,velocity,spacing,shooting,reversing,route,now,bounds)
        local flat=function(v) return Vector3.new(v.X,0,v.Z) end
        local radial=flat(basket-handler)
        if radial.Magnitude<.1 then return Core.farm_clamp(handler,bounds),nil end
        local lead=flat(velocity)*(reversing and .025 or .10)
        local limit=reversing and .5 or 1.6
        if lead.Magnitude>limit then lead=lead.Unit*limit end
        local gap=shooting and math.max(2,spacing-.9) or math.min(spacing+1.5,spacing+math.max(0,flat(velocity):Dot(radial.Unit))*.045)
        gap=math.min(gap,radial.Magnitude*.5)
        local desired=Core.farm_clamp(handler+lead+radial.Unit*gap,bounds)
        -- Once basket-side, shuffle directly: a body-avoidance detour makes the guard orbit the handler.
        if flat(origin-handler):Dot(radial.Unit)>.5 then return desired,nil end
        if reversing or route and now-(route.created or now)>.25 then route=nil end
        local waypoint,_,next_route=Core.farm_route(origin,desired,{{key="handler",position=handler,velocity=velocity}},route,now,false,bounds)
        return waypoint,next_route
    end
    function Core.guard_waypoint(origin,handler,basket,velocity,spacing,shooting,reversing,route,now,bounds,close_front,was_recovering)
        local radial=Vector3.new(basket.X-handler.X,0,basket.Z-handler.Z)
        if radial.Magnitude<.1 then return Core.farm_clamp(handler,bounds),nil,"Holding front" end
        local toward=radial.Unit
        local flat_velocity=Vector3.new(velocity.X,0,velocity.Z); local closing=flat_velocity:Dot(toward)
        local offset=Vector3.new(origin.X-handler.X,0,origin.Z-handler.Z)
        local progress=offset:Dot(toward); local lateral=(offset-toward*progress).Magnitude
        local driving=not shooting and not reversing and closing>=7 and closing>=flat_velocity.Magnitude*.6 and radial.Magnitude>3
        if driving then
            local gap=math.min(7,4+closing*.12,radial.Magnitude*.65,math.max(1,radial.Magnitude-1.3))
            local lead=(flat_velocity-toward*closing)*.10
            if lead.Magnitude>1.2 then lead=lead.Unit*1.2 end
            local intercept=Core.farm_clamp(handler+toward*gap+lead,bounds)
            local recover=progress<(was_recovering and gap-.8 or gap-1.8) or lateral>4
            return intercept,nil,recover and "Recovering rim run" or "Cutting off drive",{driving=true,recover=recover}
        end
        if close_front==false then return Core.guard_wide_waypoint(origin,handler,basket,velocity,spacing,shooting,reversing,route,now,bounds) end
        local gap=math.min(shooting and 2.6 or math.max(3.6,math.min(spacing,4.6)),radial.Magnitude*.5)
        local front=Core.farm_clamp(handler+toward*gap,bounds)
        if offset:Dot(toward)>.4 then return front,nil,"Holding front" end
        local side=Vector3.new(-toward.Z,0,toward.X); local selected,cost,sign
        for _,value in ipairs({-1,1}) do
            local point,error=Core.farm_clamp(handler+toward*gap+side*(value*3.2),bounds)
            local score=(point-origin).Magnitude+error*8-(route and route.side==value and .7 or 0)
            if not cost or score<cost then selected=point; cost=score; sign=value end
        end
        return selected,{side=sign,point=selected,created=now},"Recovering front"
    end
    function Engine:guard_summary()
        local entry=self.registry.active.guard
        if not entry then return "Auto Guard off" end
        local state=entry.state; local mine=root()
        if not state.model or not state.part or not state.part.Parent or not mine then return "Waiting for an opponent" end
        local distance=(state.part.Position-mine.Position).Magnitude
        return state.model.Name.." / "..string.format("%.1f studs",distance).." / "..(state.front_phase or "Tracking")..(state.shot_clock and " / Clock "..string.format("%.1f",state.shot_clock) or "")
    end
    function Core.guard_motion(delta,velocity,arrived,target_speed,tight)
        delta=Vector3.new(delta.X,0,delta.Z); velocity=Vector3.new(velocity.X,0,velocity.Z)
        local moving=(target_speed or 0)>4
        local arrival=tight and (arrived and (moving and .5 or .85) or (moving and .3 or .5)) or arrived and (moving and 1.1 or 1.7) or (moving and .65 or 1.05)
        local settled=delta.Magnitude<arrival and velocity.Magnitude<3.5
        if settled then return Vector3.zero,true,false end
        local correction=velocity*(tight and .08 or .14)
        if correction.Magnitude>2 then correction=correction.Unit*2 end
        local projected=delta-correction
        local braking=velocity.Magnitude>4 and (delta.Magnitude<1 or projected:Dot(delta)<0)
        if braking then return -velocity.Unit,false,true end
        return projected.Magnitude>.01 and projected.Unit or Vector3.zero,false,false
    end
    local function guard_holds(scope,state,guard,sprint)
        local failure
        for _,item in ipairs({{"guard",guard,"HoldG","G"},{"sprint",sprint,"Sprint","LeftShift"}}) do
            if (state[item[1]]==true)~=item[2] then
                local endpoint=state.actions and state.actions[item[3]]
                local ok,err=pcall(function()
                    if endpoint then
                        if item[3]=="HoldG" then endpoint:Fire({HoldingG=item[2]}) else endpoint:Fire(item[2]) end
                    else hold(scope,item[4],item[2]) end
                end)
                if ok then state[item[1]]=item[2] else failure=tostring(err) end
            end
        end
        if failure then error(failure) end
    end
    local function guard_release(scope,state)
        local ok,err=pcall(guard_holds,scope,state,false,false); release_owned(scope)
        state.steering=nil; state.keys=nil; state.arrived=nil; state.route=nil; state.pulse=nil; state.pending_contest=nil; state.tracking=nil; state.front_phase="Paused"; state.drive_recover=nil
        if not ok then ctx.report("Guard release: "..tostring(err)) end
    end
    local function guard_candidate(model,part,own,mine,a,s,state)
        if not model or not part or not part.Parent then return false end
        local hum=model:FindFirstChildOfClass("Humanoid"); if hum and hum.Health<=0 then return false end
        local team=a.Team or own:GetAttribute("Team")
        if s.team_check and team and team~=0 and team~="" and model:GetAttribute("Team")==team then return false end
        if s.ball_handler_only and not (held_ball(model) or model:GetAttribute("Basketball")==true) and not (model==state.model and os.clock()-(state.ball_seen or -10)<.35) then return false end
        local court=a.CourtNumber; local other=model:GetAttribute("CourtNumber")
        if court~=nil and other~=nil and tostring(court)~=tostring(other) then return false end
        if math.abs(part.Position.Y-mine.Position.Y)>16 or (part.Position-mine.Position).Magnitude>s.guard_range then return false end
        return not state.bounds or Core.farm_relevant(part.Position,mine.Position,state.bounds,court,other,false)
    end
    add("guard","Guard selected player","Defense","Predicts cuts, holds guard and stays on the basket side with controlled movement",{start=function(scope,s)
        assert(root(),"Enter a court before enabling Auto Guard"); assert(Engine.defensive_rim and Engine.defensive_rim.Parent,"Select your defensive rim first")
        local ok,model,part=pcall(selected_target,s)
        local state={model=ok and model or nil,part=ok and part or nil,history={},focused=true,next_target=0,last_contest=-10,shot_seen=ok and model:GetAttribute("ShotStartTime") or nil}
        local _,actions=Engine:guard_context(state,root().Position); state.actions=actions
        scope:defer(function() guard_release(scope,state) end)
        local lost=input.WindowFocusReleased:Connect(function() state.focused=false; guard_release(scope,state) end)
        scope:defer(function() lost:Disconnect() end)
        if input.WindowFocused then local c=input.WindowFocused:Connect(function() state.focused=true end); scope:defer(function() c:Disconnect() end) end
        return state
    end,step=function(scope,state,s,dt)
        local mine=root(); local own=rig(); local rim=Engine.defensive_rim
        if not mine or not own or not rim or not rim.Parent then guard_release(scope,state); return end
        if type(isrbxactive)=="function" then local ok,active=pcall(isrbxactive); if ok and type(active)=="boolean" then state.focused=active end end
        local a,actions=Engine:guard_context(state,mine.Position)
        if not state.actions and actions then
            guard_release(scope,state); state.actions=actions
        end
        if not state.focused or input:GetFocusedTextBox() or ctx.runner.current or a.CanMove==false or a.OnCourt==false or a.Fouled==true or held_ball(own) or own:GetAttribute("Basketball")==true then guard_release(scope,state); return end
        finish_pulse(scope,state)
        if os.clock()>=state.next_target or state.part and not state.part.Parent then
            state.next_target=os.clock()+.15
            local ok,model,part
            if s.guard_target=="" then
                local list={}
                for _,who in ipairs(players:GetPlayers()) do if who~=ctx.player then
                    local model2,part2=rig(who),root(who)
                    if guard_candidate(model2,part2,own,mine,a,s,state) then
                        list[#list+1]={key=model2,part=part2,position=part2.Position,has_ball=held_ball(model2)~=nil or model2:GetAttribute("Basketball")==true}
                    end
                end end
                local chosen=Core.guard_choose(list,mine.Position,state.model,os.clock()-(state.ball_seen or -10)<.35)
                if chosen then model=chosen.key; part=chosen.part end
                ok=model~=nil
            else ok,model,part=pcall(selected_target,s) end
            if not ok then state.model=nil; state.part=nil; guard_release(scope,state); return end
            if model~=state.model or part~=state.part then
                guard_release(scope,state); state.history={}; state.model=model; state.part=part
                state.shot_seen=model:GetAttribute("ShotStartTime")
            end
        end
        if not state.model or not state.part or not state.part.Parent then guard_release(scope,state); return end
        local target=state.model; local position=state.part.Position
        if not guard_candidate(target,state.part,own,mine,a,s,state) then guard_release(scope,state); return end
        if held_ball(target) or target:GetAttribute("Basketball")==true then state.ball_seen=os.clock() end
        state.tracking=state.tracking or {}
        local velocity,reversing=Core.guard_observe(state.tracking,position,state.part.AssemblyLinearVelocity,os.clock())
        if reversing then state.route=nil; state.steering=nil; state.arrived=nil end
        local mine_velocity=Core.farm_observe(state.history,"self",mine.Position,os.clock(),mine.AssemblyLinearVelocity)
        local shooting=target:GetAttribute("InAir")==true and (target:GetAttribute("ShotStartTime")~=nil or target:GetAttribute("Action")=="Shooting")
        local shot=target:GetAttribute("ShotStartTime")
        if type(shot)=="number" and shot~=state.shot_seen then state.shot_seen=shot; state.pending_contest=os.clock() end
        if state.pending_contest and os.clock()-state.pending_contest>.7 then state.pending_contest=nil end
        if s.guard_contest and not registry.active.block and not registry.active.rebound and state.pending_contest and shooting and a.InAir~=true and os.clock()-state.pending_contest>=s.block_delay and os.clock()-state.last_contest>1.1 and (position-mine.Position).Magnitude<=math.min(s.block_range,9) then
            if state.actions and state.actions.Jump then state.actions.Jump:Fire() else pulse(scope,state,jump_key(s)) end
            state.last_contest=os.clock(); state.pending_contest=nil
        end
        state.shot_clock=Engine:read_shot_clock(state,a.CourtNumber)
        local waypoint,route,phase,tactics=Core.guard_waypoint(mine.Position,position,rim.Position,velocity,s.guard_distance,shooting,reversing,state.route,os.clock(),state.bounds,s.guard_close_front,state.drive_recover)
        state.drive_recover=tactics and tactics.recover or false
        state.front_phase=phase
        state.route=route
        local delta=Vector3.new(waypoint.X-mine.Position.X,0,waypoint.Z-mine.Position.Z)
        local camera=camera_service(); local forward=Vector3.new(camera.CFrame.LookVector.X,0,camera.CFrame.LookVector.Z)
        local right=Vector3.new(camera.CFrame.RightVector.X,0,camera.CFrame.RightVector.Z)
        if forward.Magnitude<.01 or right.Magnitude<.01 then guard_release(scope,state); return end
        local direction,arrived,braking=Core.guard_motion(delta,mine_velocity,state.arrived,velocity.Magnitude,s.guard_close_front)
        state.arrived=arrived; state.braking=braking
        if not s.guard_close_front then direction=Core.farm_smooth(state.steering,direction,dt) end; state.steering=direction
        local f=direction:Dot(forward.Unit); local r=direction:Dot(right.Unit)
        local threshold=.3/math.max(.5,s.guard_strength); local keys={}
        for _,entry in ipairs({{"W",f},{"S",-f},{"D",r},{"A",-r}}) do
            if entry[2]>(state.keys and state.keys[entry[1]] and threshold*.75 or threshold) then keys[entry[1]]=true end
        end
        if state.bounds then keys=Core.farm_safe_keys(keys,mine.Position,forward.Unit,right.Unit,mine_velocity,state.bounds) end
        state.keys=keys
        for _,key in ipairs({"W","S","A","D"}) do hold(scope,key,keys[key]==true) end
        local stamina=tonumber(a.Stamina or own:GetAttribute("Stamina"))
        if stamina then if stamina<25 then state.fatigued=true elseif stamina>=40 then state.fatigued=false end end
        local _,_,edge=Core.farm_clamp(mine.Position,state.bounds)
        local recovering=state.drive_recover and next(keys)~=nil
        local sprint=(recovering and delta.Magnitude>.5 or s.guard_sprint and delta.Magnitude>7) and next(keys)~=nil and not state.braking and not state.fatigued and (not state.bounds or edge>5)
        guard_holds(scope,state,not recovering,sprint)
    end,interval=1/60,conflicts={"fly","spin"}})
    add("block","Block selected shooter","Defense","Pulses your jump key after a new observed ShotStartTime and InAir state",{start=function(scope,s)
