        s.ball_color=name=="Galaxy" and "#7061CE" or name=="Neon" and "#9AC9FF" or name=="Matte" and "#323744" or "#D5DCE8"
        s.ball_glow=name=="Neon" or name=="Galaxy"; s.ball_remove_texture=true
    end
    function Engine:apply_court_preset(name)
