            for key,item in pairs(state.buttons) do local on=state.connected and state.values[key]; item.part.BackgroundColor3=on and (item.color or palette.accent) or palette.base; item.label.TextColor3=on and palette.base or item.color or palette.text
                item.part.BackgroundTransparency=asset and (on and 1-.65*settings.controller_opacity or 1) or 0
