        for i=1,24 do parts[i]=tool_object(scope,"Part",{Name="EstimateRing",Anchored=true,CanCollide=false,CanTouch=false,CanQuery=false,CastShadow=false,Material=Enum.Material.Neon,Transparency=1},folder) end
