        local fill=Instance.new("Frame"); fill.Name="PerfectBar"; fill.Size=UDim2.fromScale(0,1); fill.BackgroundColor3=Color3.fromRGB(147,189,165); fill.BorderSizePixel=0; fill.Parent=track
