    local function farm_ready(q,value)
        q.Ready=value
        if q.ReadyButton then q.ReadyButton:SwitchConfig({Text=value and "UNREADY" or "READY",
            Color=value and Color3.fromRGB(6,85,255) or Color3.fromRGB(0,207,97)}) end
    end
    local function farm_actions(state,guard,sprint)
        if not state.actions then return end
        if state.stamina then
            if state.stamina<25 then state.fatigued=true elseif state.stamina>=40 then state.fatigued=false end
            if state.fatigued then sprint=false end
        end
        local failure
        for _,item in ipairs({{"guard",guard,"HoldG"},{"sprinting",sprint,"Sprint"}}) do
            if (state[item[1]]==true)~=item[2] then
                local ok,err=pcall(function()
                    if item[3]=="HoldG" then state.actions.HoldG:Fire({HoldingG=item[2]})
                    else state.actions.Sprint:Fire(item[2]) end
                end)
                if ok then state[item[1]]=item[2] else failure=tostring(err) end
            end
        end
        if failure then error("Guard/sprint input failed: "..failure) end
    end
    local function farm_release(scope,state)
        release_owned(scope); farm_actions(state,false,false); state.steering=nil; state.steering_keys=nil; state.arrived=nil
    end
    local function farm_flat(v) return Vector3.new(v.X,0,v.Z) end
    local function farm_cap(v,limit) return v.Magnitude>limit and v.Unit*limit or v end
    function Core.farm_observe(history,key,position,now,reported)
        local old=history[key]; local velocity=Vector3.new(0,0,0)
        if old and now-old.time>=.008 and now-old.time<=.5 then
            velocity=farm_flat(position-old.position)/(now-old.time)
            if velocity.Magnitude>65 then velocity=Vector3.new(0,0,0) end
        end
        if reported and typeof(reported)=="Vector3" and farm_flat(reported).Magnitude>.1 and farm_flat(reported).Magnitude<65 then velocity=farm_flat(reported) end
        velocity=farm_cap(velocity,40)
        if old and old.velocity and old.velocity:Dot(velocity)>0 then velocity=old.velocity*.4+velocity*.6 end
        history[key]={position=position,time=now,velocity=velocity}; return velocity
    end
    function Core.farm_guard_goal(handler,basket,velocity,shooting)
        velocity=farm_flat(velocity or Vector3.new(0,0,0))
        local toward=farm_flat(basket-handler)
        if toward.Magnitude<.1 then return handler end
        local lead=farm_cap(velocity*.16,2.4)
        local spacing=shooting and 2.6 or math.min(5.2,3.5+math.max(0,velocity:Dot(toward.Unit))*.065)
        local predicted=handler+lead; local radial=farm_flat(basket-predicted)
        return predicted+(radial.Magnitude>.1 and radial.Unit*math.min(spacing,radial.Magnitude*.5) or Vector3.new(0,0,0))
    end
    function Core.farm_clamp(point,bounds)
        if not bounds then return point,0,math.huge end
        local local_point=bounds.frame:PointToObjectSpace(point)
        local x=math.max(-bounds.x,math.min(bounds.x,local_point.X)); local z=math.max(-bounds.z,math.min(bounds.z,local_point.Z))
        local world=bounds.frame:PointToWorldSpace(Vector3.new(x,local_point.Y,z))
        return world,farm_flat(world-point).Magnitude,math.min(bounds.x-math.abs(x),bounds.z-math.abs(z))
    end
    function Core.farm_playable_area(parts,origin)
        local reference=parts[1]; if not reference then return nil end
        local frame=reference.CFrame; local xs,zs={},{}
        for _,part in ipairs(parts) do
            if part:IsA("BasePart") and math.abs(part.CFrame.UpVector.Y)>.98 then
                local minx,minz,maxx,maxz=math.huge,math.huge,-math.huge,-math.huge
                for _,x in ipairs({-part.Size.X/2,part.Size.X/2}) do for _,z in ipairs({-part.Size.Z/2,part.Size.Z/2}) do
                    local p=frame:PointToObjectSpace(part.CFrame:PointToWorldSpace(Vector3.new(x,0,z)))
                    minx=math.min(minx,p.X); maxx=math.max(maxx,p.X); minz=math.min(minz,p.Z); maxz=math.max(maxz,p.Z)
                end end
                if maxx-minx>(maxz-minz)*2.5 then zs[#zs+1]={low=minz,high=maxz}
                elseif maxz-minz>(maxx-minx)*2.5 then xs[#xs+1]={low=minx,high=maxx} end
            end
        end
        table.sort(xs,function(a,b) return a.low<b.low end); table.sort(zs,function(a,b) return a.low<b.low end)
        local best,score
        for i=1,#xs-1 do for j=1,#zs-1 do
            local left,right,bottom,top=xs[i].high,xs[i+1].low,zs[j].high,zs[j+1].low
            local width,depth=right-left,top-bottom
            if width>=20 and depth>=20 and width<=250 and depth<=180 then
                local centered=frame*CFrame.new((left+right)/2,0,(bottom+top)/2)
                local b={part=reference,markers=parts,frame=centered,x=width/2-5,z=depth/2-5,verified=true}
                local _,distance=Core.farm_clamp(origin,b)
                local cost=distance*100+farm_flat(centered.Position-origin).Magnitude*.01
                if distance<=5.5 and (not score or cost<score) then best=b; score=cost end
            end
        end end
        return best
    end
    function Core.farm_safe_keys(requested,origin,forward,right,velocity,bounds)
        if not bounds then return {},true end
        velocity=farm_cap(farm_flat(velocity or Vector3.new(0,0,0)),45)
        local drift=origin+velocity*.3; local correction,overflow=Core.farm_clamp(drift,bounds); correction=farm_flat(correction-drift)
        local entries={{"W",forward},{"S",-forward},{"D",right},{"A",-right}}
        local desired=Vector3.new(0,0,0)
        for _,entry in ipairs(entries) do if requested[entry[1]] then desired=desired+entry[2] end end
        if desired.Magnitude>.01 then desired=desired.Unit end
        local chosen,best={},-math.huge
        for mask=1,15 do
            local keys={}; local direction=Vector3.new(0,0,0); local allowed=true
            for i,entry in ipairs(entries) do if math.floor(mask/2^(i-1))%2==1 then
                keys[entry[1]]=true; direction=direction+entry[2]
                if not requested[entry[1]] and overflow<.05 then allowed=false end
            end end
            if keys.W and keys.S or keys.A and keys.D then allowed=false end
            if allowed and direction.Magnitude>.01 then
                direction=direction.Unit
                local future=drift+direction*math.max(2.5,math.min(7,velocity.Magnitude*.2))
                local _,error=Core.farm_clamp(future,bounds)
