            local point=predicted+side*(sign*7)+forward*5
            local progress=farm_flat(point-origin):Dot(forward)
            if progress<4 then point=point+forward*(4-progress) end
            local clipped,edge=Core.farm_clamp(point,bounds); point=clipped
            local clearance=Core.farm_clearance(origin,point,opponents)
            local score=farm_flat(point-origin).Magnitude*.65+farm_flat(goal-point).Magnitude+edge*12+math.max(0,3.5-clearance)*14
            for _,other in ipairs(opponents) do score=score+math.max(0,8-farm_flat(other.position-point).Magnitude)*5 end
            if route and route.side==sign then score=score-2 end
            if not cost or score<cost then chosen=point; cost=score; chosen_side=sign end
        end
        route={key=blocker.key,blocker=blocker.position,point=Vector3.new(chosen.X,origin.Y,chosen.Z),created=now,side=chosen_side,until_time=now+1.1}
        return route.point,true,route
    end
    local function farm_opponents(model,state,origin)
        local list,teammates={},{}; local team=state.team or model:GetAttribute("Team")
        for _,who in ipairs(players:GetPlayers()) do if who~=ctx.player then
            local other=rig(who); local point=root(who)
            local teammate=team and team~=0 and team~="" and other and other:GetAttribute("Team")==team
            local hum=other and other:FindFirstChildOfClass("Humanoid")
            if other and point and (not hum or hum.Health>0) and Core.farm_relevant(point.Position,origin,state.bounds,state.boundary_court,other:GetAttribute("CourtNumber"),false) then
                local ball=held_ball(other)
                local velocity=Core.farm_observe(state.history,who,point.Position,os.clock(),point.AssemblyLinearVelocity)
                local target=teammate and teammates or list
                target[#target+1]={key=who,model=other,position=point.Position,velocity=velocity,part=point,ball=ball,has_ball=ball~=nil or other:GetAttribute("Basketball")==true,down=Core.farm_defender_down(other,point)}
            end
        end end
        for key,item in pairs(state.history) do if os.clock()-item.time>5 then state.history[key]=nil end end
        return list,teammates
    end
    local function farm_basket(state,attributes,origin,defending)
        local rims={}
        for _,item in ipairs(candidates("rims")) do
            local rim=item.object; local _,outside=Core.farm_clamp(rim.Position,state.bounds)
            if rim.Parent and outside<12 and math.abs(rim.Position.Y-origin.Y)<25 then rims[#rims+1]=rim end
        end
        if #rims==0 then return nil end
        local value=attributes.Goal; local kind=type(typeof)=="function" and typeof(value) or type(value)
        local reference,point
        if kind=="Vector3" then point=value
        elseif kind=="CFrame" then point=value.Position
        elseif kind=="Instance" or type(value)=="table" and value.ClassName and type(value.IsA)=="function" then
            reference=value
            if value:IsA("BasePart") then point=value.Position
            elseif value:IsA("Model") and value.PrimaryPart then point=value.PrimaryPart.Position end
        end
        local linked,linked_count,nearest,nearest_distance=nil,0,nil,math.huge
        for _,rim in ipairs(rims) do
            if reference and (rim==reference or rim:IsDescendantOf(reference)) then linked=rim; linked_count=linked_count+1 end
            if point then local d=farm_flat(rim.Position-point).Magnitude; if d<nearest_distance then nearest=rim; nearest_distance=d end end
        end
        local offense=linked_count==1 and linked or point and nearest_distance<18 and nearest or nil
        if defending and Engine.defensive_rim then for _,rim in ipairs(rims) do if rim==Engine.defensive_rim then state.basket_source="Selected defensive rim"; return rim end end end
        if not defending and offense then state.basket_source="Game shooting goal"; return offense end
        if defending and offense and #rims>1 then
            local other,distance
            for _,rim in ipairs(rims) do local d=farm_flat(rim.Position-offense.Position).Magnitude; if not distance or d>distance then other=rim; distance=d end end
            state.basket_source="Opposite game shooting goal"; return other
        end
        if not defending and state.attack_basket then for _,rim in ipairs(rims) do if rim==state.attack_basket then return rim end end end
        local best,distance
        for _,rim in ipairs(rims) do local d=farm_flat(rim.Position-origin).Magnitude; if not distance or d<distance then best=rim; distance=d end end
        state.basket_source=#rims==1 and "Single playable basket" or "Nearest playable basket"; return best
    end
    local function farm_sample_ball(state,ball)
        local old=state.ball_sample; local velocity=ball.AssemblyLinearVelocity
        if not velocity or type(typeof)=="function" and typeof(velocity)~="Vector3" then velocity=Vector3.zero end
        if velocity.Magnitude<.1 and old and old.ball==ball and os.clock()-old.time>=.025 and os.clock()-old.time<.5 then velocity=(ball.Position-old.position)/(os.clock()-old.time) end
        if velocity.Magnitude>120 then velocity=Vector3.zero end
        state.ball_sample={ball=ball,position=ball.Position,time=os.clock()}; return velocity
    end
    local function farm_bounds(state,s,origin,court_number)
        if state.boundary_court~=court_number then state.bounds=nil; state.next_bounds=0; state.boundary_court=court_number; state.clear_radius=nil; state.clear_target=nil end
        if state.bounds then
            local valid=true
            for _,marker in ipairs(state.bounds.markers or {}) do if not marker.Parent or not marker:IsDescendantOf(workspace) then valid=false; break end end
            if valid and state.bounds.verified then return state.bounds end
            state.bounds=nil
        end
        if os.clock()<(state.next_bounds or 0) then return nil end
        state.next_bounds=os.clock()+2
        local roots,seen,groups={}, {},{}
        for _,name in ipairs({"Map","Courts","Court"}) do local folder=workspace:FindFirstChild(name); if folder then roots[#roots+1]=folder end end
        local assets=workspace:FindFirstChild("Assets"); local court=assets and assets:FindFirstChild("Court")
        if court then roots[#roots+1]=court end
        if #roots==0 then roots[1]=workspace end
        local function collect(group)
            if seen[group] or group.Name:lower()~="outofbounds" then return end
            seen[group]=true; groups[#groups+1]=group
        end
        for _,folder in ipairs(roots) do collect(folder); for _,child in ipairs(folder:GetDescendants()) do collect(child) end end
        local best,best_cost
        for _,group in ipairs(groups) do
            local parts={}
            for _,part in ipairs(group:GetDescendants()) do
                if part:IsA("BasePart") and math.abs(part.Position.Y-origin.Y)<20 and math.abs(part.CFrame.UpVector.Y)>.98 then parts[#parts+1]=part end
            end
            local bounds=Core.farm_playable_area(parts,origin)
            if bounds then
                local _,distance=Core.farm_clamp(origin,bounds)
                local cost=distance*100+farm_flat(bounds.frame.Position-origin).Magnitude*.01
                if not best_cost or cost<best_cost then best=bounds; best_cost=cost; bounds.source=group:GetFullName() end
            end
        end
        state.bounds=best; return best
    end
    function Engine:guard_context(state,origin)
        local ok,c=pcall(local_state)
        local attrs=ok and c and c.data and c.data.Attributes or {}
        farm_bounds(state,self.settings,origin,attrs.CourtNumber)
        local good,_,keyboard=pcall(client_parts)
        return attrs,good and keyboard and keyboard.Services and keyboard.Services.InputService or nil
    end
    local function farm_boundary_report(state,origin)
        if os.clock()<(state.next_diagnostic or 0) then return end
        state.next_diagnostic=os.clock()+2
        pcall(function()
            local b=state.bounds; local point=b and b.frame:PointToObjectSpace(origin)
            writefile("vanta_badge_farm_runtime.json",farm_http:JSONEncode({build="2026.11.08.08",status=Engine.farm_status,role=state.role,basketSource=state.basket_source,shotClearance=state.shot_clearance and math.min(999,state.shot_clearance),stats=Engine.farm_stats,
                position={origin.X,origin.Y,origin.Z},bounds=b and {source=b.source,x=b.x,z=b.z,localPosition={point.X,point.Y,point.Z}} or false,
                boundaryBrake=state.boundary_braking==true,guard=state.guard==true,sprint=state.sprinting==true,keys=state.steering_keys or {}}))
        end)
    end
    local function farm_steer(scope,state,goal,guard)
        local mine=root(); if not mine or not goal then farm_release(scope,state); return end
        if not state.bounds or not state.bounds.verified then farm_release(scope,state); state.boundary_braking=true; return end
        local clamped_goal,_,target_edge=Core.farm_clamp(goal,state.bounds); goal=clamped_goal
        local safe,overflow=Core.farm_clamp(mine.Position,state.bounds)
        if overflow>.05 then goal=safe end
        local _,drifting=Core.farm_clamp(mine.Position+(state.velocity or Vector3.zero)*.3,state.bounds)
        state.nav_recovering=false
        if overflow<.05 and drifting<.05 then
            local recovering,started
            goal,recovering,started=Core.farm_navigation(state,mine.Position,goal,os.clock(),state.bounds)
            state.nav_recovering=recovering
            if started then Engine.farm_stats.recoveries=Engine.farm_stats.recoveries+1 end
        else state.escape_until=nil; state.nav_time=nil end
        local d=goal-mine.Position; d=Vector3.new(d.X,0,d.Z)
        local cam=workspace.CurrentCamera
        if not cam then farm_release(scope,state); return end
        local f=cam.CFrame.LookVector; f=Vector3.new(f.X,0,f.Z)
        local r=cam.CFrame.RightVector; r=Vector3.new(r.X,0,r.Z)
        if f.Magnitude<.01 or r.Magnitude<.01 then farm_release(scope,state); return end
        local arrival=overflow>.05 and .08 or target_edge<1 and 3.2 or guard and .65 or 1.7
        state.arrived=d.Magnitude<arrival or state.arrived and d.Magnitude<arrival+.7
        local velocity=state.velocity or Vector3.new(0,0,0)
        local braking=d.Magnitude>0 and d.Magnitude<5 and velocity:Dot(d.Unit)>d.Magnitude*5
        if state.arrived or braking then
            local recovery,blocked=Core.farm_safe_keys({},mine.Position,f.Unit,r.Unit,velocity,state.bounds)
            release_owned(scope); state.steering=nil; state.steering_keys=recovery; state.boundary_braking=blocked
            for _,key in ipairs({"W","S","D","A"}) do hold(scope,key,recovery[key]==true) end
            farm_actions(state,guard==true,false); return
        end
        state.steering=Core.farm_smooth(state.steering,d.Unit,state.dt)
        local forward,right=state.steering:Dot(f.Unit),state.steering:Dot(r.Unit)
        local previous=state.steering_keys or {}; local requested={}
        for _,entry in ipairs({{"W",forward},{"S",-forward},{"D",right},{"A",-right}}) do
            local key,value=entry[1],entry[2]; requested[key]=value>(previous[key] and .12 or .38)
        end
        local keys,blocked=Core.farm_safe_keys(requested,mine.Position,f.Unit,r.Unit,velocity,state.bounds)
        state.steering_keys=keys; state.boundary_braking=blocked
        for _,key in ipairs({"W","S","D","A"}) do hold(scope,key,keys[key]==true) end
        local _,_,edge=Core.farm_clamp(mine.Position,state.bounds)
        farm_actions(state,guard==true,next(keys)~=nil and not blocked and not state.nav_recovering and d.Magnitude>(guard and 8 or 5) and edge>5)
    end
    function Core.farm_drive_lane(origin,basket,opponents,bounds)
        local toward=farm_flat(basket-origin); local distance=toward.Magnitude
        if not bounds or distance<.1 or distance>34 then return nil end
        local finish=basket-toward.Unit*1.5; finish=Vector3.new(finish.X,origin.Y,finish.Z)
        local target,error,edge=Core.farm_clamp(finish,bounds)
        if error>.1 or edge<1 then return nil end
        local active={}; for _,other in ipairs(opponents) do if not other.down then active[#active+1]=other end end
        if Core.farm_clearance(origin,target,active)<4.5 or Core.farm_shot_clearance(target,active,.45)<5 then return nil end
        return target,distance
    end
    function Core.farm_takeback_target(origin,basket,opponents,bounds,radius)
        local best,cost
        for i=0,23 do
            local angle=i*math.pi/12; local target=Vector3.new(basket.X+math.cos(angle)*(radius+3),origin.Y,basket.Z+math.sin(angle)*(radius+3))
            local clipped,error,edge=Core.farm_clamp(target,bounds)
            if error<.1 and edge>1 then
                local score=farm_flat(target-origin).Magnitude+math.max(0,5-Core.farm_clearance(origin,target,opponents))*5
                if not cost or score<cost then best=clipped; cost=score end
            end
        end
        return best
    end
    local function farm_clear_radius(state)
        if state.clear_radius then return state.clear_radius end
        local group=state.bounds and state.bounds.markers and state.bounds.markers[1]
        group=group and group.Parent and group.Parent.Parent
        if group then for _,part in ipairs(group:GetDescendants()) do
            if part:IsA("BasePart") and court_line_kind(part)=="three" then
                local size=math.max(part.Size.X,part.Size.Z)
                if size>=40 and size<=90 then state.clear_radius=size*.5+2; return state.clear_radius end
            end
        end end
        return 36
    end
    local function farm_takeback(scope,state,model,mine,basket,opponents,attributes)
        if attributes.NeedsClear==true or attributes.NeedClear==true or attributes.MustClear==true then state.need_takeback=true end
        if not state.need_takeback then return false end
        local radius=farm_clear_radius(state)
        local ball=held_ball(model)
        local own_distance=farm_flat(mine.Position-basket.Position).Magnitude
        local ball_distance=ball and farm_flat(ball.Position-basket.Position).Magnitude or own_distance
        if own_distance>=radius+1 and ball_distance>=radius+1 then
            state.clear_since=state.clear_since or os.clock()
            if os.clock()-state.clear_since>=.15 then
                state.need_takeback=false; state.opponent_shot_pending=false; state.clear_target=nil; state.clear_since=nil
                return false
            end
        else state.clear_since=nil end
        if own_distance>=radius+1 and ball_distance>=radius+1 then farm_release(scope,state)
        else
            local target=state.clear_target or Core.farm_takeback_target(mine.Position,basket.Position,opponents,state.bounds,radius)
            state.clear_target=target
            if target then
                local waypoint,_,route=Core.farm_route(mine.Position,target,opponents,state.offense_route,os.clock(),true,state.bounds)
                state.offense_route=route; farm_steer(scope,state,waypoint,false)
            else farm_release(scope,state) end
        end
        state.takeback_phase="Taking ball back beyond three-point line"
        return true
    end
    add("badge_farm","Blacktop badge farm","Player","Queues and plays Blacktop matches; badge rewards are decided by the game",{
        start=function(scope,s)
            assert(s.farm_mode:match("^[1-5]v[1-5]$") and s.farm_mode:sub(1,1)==s.farm_mode:sub(3,3),"Choose 1v1–5v5")
            assert(type(readfile)=="function" and type(writefile)=="function","Badge loop requires readfile/writefile")
            local queue=queue_on_teleport or (syn and syn.queue_on_teleport)
            assert(type(queue)=="function","Badge loop requires queue_on_teleport to continue between places")
            local state={alive=true,busy=false,next_at=0,owned={},last_shot=-10,teleporting=false,queue_owned=false,focused=true,history={},last_jump=-10}
            local focus_lost=input.WindowFocusReleased:Connect(function()
                state.focused=false; state.shot_ready_since=nil; farm_release(scope,state)
                if state.adapter and Engine.auto_shoot_held then pcall(state.adapter.release); Engine.auto_shoot_held=false end
            end)
            scope:defer(function() focus_lost:Disconnect() end)
            if input.WindowFocused then local link=input.WindowFocused:Connect(function() state.focused=true end); scope:defer(function() link:Disconnect() end) end
            local teleport=ctx.player.OnTeleport
            if teleport then local c=teleport:Connect(function(phase) if phase==Enum.TeleportState.Started or phase==Enum.TeleportState.InProgress then state.teleporting=true end; if phase==Enum.TeleportState.Failed then state.teleporting=false end end); scope:defer(function() c:Disconnect() end) end
            scope:defer(function()
                state.alive=false; local released,err=pcall(farm_release,scope,state); if not released then ctx.report(tostring(err)) end
                if state.adapter and Engine.auto_shoot_held then pcall(state.adapter.release); Engine.auto_shoot_held=false end
                for id in pairs(state.owned) do registry:disable(id) end
                if not (state.teleporting and Engine.farm_closing) then pcall(farm_write,false) end
                if not state.teleporting then
                    if state.queue_owned and state.queue and workspace:GetAttribute("Gamemode")=="BlacktopMatchmaking" then
                        task.spawn(function() pcall(function() local ok=state.queue.Services.QueueService:Ready(false); if ok then farm_ready(state.queue,false) end end) end)
                    end
                end
                Engine.farm_status="Off"
            end)
            farm_session=tostring(os.time())..":"..tostring(os.clock())
            farm_write(true)
            queue([[local ok,c=pcall(function() return game:GetService("HttpService"):JSONDecode(readfile("vanta_badge_farm.json")) end)
if ok and c.enabled==true and c.session==]]..string.format("%q",farm_session)..[[ then loadstring(game:HttpGet("https://raw.githubusercontent.com/zyhnq/fuckyoumatthew/main/pivot_launcher.lua?v=20261108.08"))() end]])
            Engine.farm_status="Starting"; return state
        end,
        step=function(scope,state,s,dt)
            state.dt=dt or .05
            if state.busy or state.teleporting or os.clock()<state.next_at then return end
            local function status(value) if Engine.farm_status~=value then Engine.farm_status=value; ctx.report("Badge farm / "..value) end end
            if type(isrbxactive)=="function" then local ok,active=pcall(isrbxactive); if ok and type(active)=="boolean" then state.focused=active end end
            if not state.focused then state.combo=nil; farm_release(scope,state); status("Paused while Roblox is unfocused"); return end
            if input:GetFocusedTextBox() or ctx.runner.current then state.combo=nil; farm_release(scope,state); status("Paused while typing or running a combo"); return end
            local signature=s.farm_mode..tostring(s.farm_any_region)..tostring(s.farm_auto_play)..tostring(s.farm_shot_range)..tostring(s.farm_dribble)..tostring(s.farm_open_drive)..tostring(s.farm_dribble_all)..tostring(s.farm_chains)..tostring(s.farm_hop_gathers)..tostring(s.farm_varied_shots)..tostring(s.farm_three_range)
            if state.saved~=signature then farm_write(true); state.saved=signature end
            local mode=workspace:GetAttribute("Gamemode")
            local ok,gui=pcall(farm_controllers)
            if not ok then farm_release(scope,state); status("Waiting for game controllers"); state.next_at=os.clock()+1; return end
            local function request(label,call,done)
                state.busy=true; status(label)
                task.spawn(function()
                    local accepted,a,b=pcall(call)
                    state.busy=false; state.next_at=os.clock()+(accepted and a~=false and 1.5 or 8)
                    if not state.alive then
                        if done and accepted and a==true then done(true) end
                        return
                    end
                    if not accepted or a~=true then status("Request failed: "..tostring(accepted and (b or "rejected") or a))
                    elseif done then local good,err=pcall(done,false); if not good then status("Request completion failed: "..tostring(err)) end end
                end)
            end
            if mode=="BlacktopMatchmaking" then
                farm_release(scope,state)
                local q=gui:GetComponent("Queue")
                if not q or not q.Services or not q.Services.QueueService then status("Waiting for Blacktop queue"); return end
                state.queue=q
                if q.partyInfo and q.partyInfo.Owner and q.partyInfo.Owner~=ctx.player then status("Waiting for the party leader"); return end
                if q.Loading and q.Loading.Showing then status("Match found / waiting for teleport"); return end
                if q.InQueue or q.Ready then
                    state.search_started=state.search_started or os.clock()
                    if state.queue_owned and (ctx.player:GetAttribute("QueueMode")~=s.farm_mode or (ctx.player:GetAttribute("AnyRegion")==true)~=s.farm_any_region) then
                        request("Updating queue settings",function() return q.Services.QueueService:Ready(false) end,function() state.queue_owned=false; farm_ready(q,false) end)
                    elseif state.queue_owned and os.clock()-state.search_started>120 then
                        request("Refreshing stalled queue",function() return q.Services.QueueService:Ready(false) end,function() state.queue_owned=false; state.search_started=nil; Engine.farm_stats.requeues=Engine.farm_stats.requeues+1; farm_ready(q,false) end)
                    else status("Searching for "..tostring(ctx.player:GetAttribute("QueueMode") or s.farm_mode).." match") end
                    return
                end
                state.search_started=nil
                if q.Active==false then status("Open the public Blacktop queue"); return end
                local service=q.Services.QueueService
                if ctx.player:GetAttribute("QueueMode")~=s.farm_mode then
                    request("Selecting "..s.farm_mode,function() return service:SelectMode(s.farm_mode) end); return
                end
                if (ctx.player:GetAttribute("AnyRegion")==true)~=s.farm_any_region then
                    request("Updating region",function() return service:SetAnyRegion(s.farm_any_region) end); return
                end
                request("Joining queue",function() return service:Ready(true) end,function(stopped)
                    if stopped then pcall(function() service:Ready(false) end)
                    else state.queue_owned=true; farm_ready(q,true); farm_write(true) end
                end)
                return
            end
            if mode~="Blacktop" then farm_release(scope,state); status("Join public Blacktop matchmaking"); return end
            local summary=gui:GetComponent("Summary")
            if summary and summary.Active==true and not state.result_seen then
                state.result_seen=true; state.return_at=math.min(os.clock()+90,math.max(os.clock()+15,(tonumber(summary.ActiveUntil) or 0)+2))
                Engine.farm_matches=Engine.farm_matches+1; Engine.farm_badge_lines={}
                local pg=ctx.player:FindFirstChild("PlayerGui")
                if pg then for _,o in ipairs(pg:GetDescendants()) do
                    local path=o:GetFullName():lower()
                    if o:IsA("TextLabel") and o.Visible and #Engine.farm_badge_lines<20 and (path:find("summary",1,true) or path:find("breakdown",1,true)) and (o.Text:lower():find("badge",1,true) or path:find("badge",1,true)) then
                        Engine.farm_badge_lines[#Engine.farm_badge_lines+1]=o.Text:sub(1,120)
                    end
                end end
                farm_write(true)
            end
            if state.result_seen then
                farm_release(scope,state); status("Match complete / waiting for postgame display")
                if os.clock()>=state.return_at then
                    state.return_attempts=(state.return_attempts or 0)+1
                    state.return_at=os.clock()+math.min(60,10*state.return_attempts)
                    request("Returning to matchmaking",function()
                        game:GetService("TeleportService"):Teleport(78438427735992,ctx.player); return true
                    end)
                end
                return
            end
            if not s.farm_auto_play then farm_release(scope,state); status("Match active / auto play off"); return end
            local success,c=pcall(local_state); local mine=root(); local model=rig()
            if not success or not c or not c.data or not c.data.Attributes or not mine or not model then farm_release(scope,state); status("Waiting for spawned court character"); return end
            state.velocity=Core.farm_observe(state.history,"self",mine.Position,os.clock(),mine.AssemblyLinearVelocity)
            farm_bounds(state,s,mine.Position,c.data.Attributes.CourtNumber)
            farm_boundary_report(state,mine.Position)
            if not state.bounds then state.shot_ready_since=nil; farm_release(scope,state); status("Movement paused / playable boundary markers unavailable"); return end
            if not state.actions then
                local good,_,keyboard=pcall(client_parts)
                local actions=good and keyboard and keyboard.Services and keyboard.Services.InputService
                if not actions or not actions.HoldG or not actions.Sprint then farm_release(scope,state); status("Guard/sprint controls unavailable"); state.next_at=os.clock()+3; return end
                state.actions=actions
            end
            local a=c.data.Attributes
            state.stamina=tonumber(a.Stamina); state.team=a.Team or model:GetAttribute("Team")
            state.shot_clock=Engine:read_shot_clock(state,a.CourtNumber); Engine.farm_clock=state.shot_clock
            if not state.adapter then local ready,adapter=pcall(shooting_adapter); if not ready then status("Waiting for shooting controls"); return end; state.adapter=adapter end
            if a.OnCourt==false or a.CanMove==false and not Engine.auto_shoot_held or a.Fouled==true then
                state.shot_ready_since=nil; farm_release(scope,state)
                if Engine.auto_shoot_held then state.adapter.release(); Engine.auto_shoot_held=false end
                status("Waiting for playable possession"); return
            end
            if not registry.active.meter_release then
                local enabled,err=registry:enable("meter_release",s)
                if not enabled then farm_release(scope,state); status("Auto Green unavailable: "..tostring(err)); state.next_at=os.clock()+3; return end
                state.owned.meter_release=true
            end
            local safe_drift,drift_error=Core.farm_clamp(mine.Position+state.velocity*.3,state.bounds)
            local safe_position,position_error=Core.farm_clamp(mine.Position,state.bounds)
            if drift_error>.1 or position_error>.05 then
                state.combo=nil
                state.shot_ready_since=nil
                if Engine.auto_shoot_held then state.adapter.release(); Engine.auto_shoot_held=false end
                farm_steer(scope,state,position_error>.05 and safe_position or safe_drift,not (held_ball(model) or model:GetAttribute("Basketball")==true))
                status("Boundary brake / returning inside"); return
            end
            if Engine.auto_shoot_held then
                farm_release(scope,state)
                if os.clock()-state.last_shot>1.5 then state.adapter.release() end
                status("Timing shot"); return
            end
            local dribbling=type(a.Action)=="string" and a.Action:lower():find("dribbl",1,true)~=nil
            if a.Action and a.Action~="" and a.Action~="Guard" and a.Action~="Guarding" and not dribbling then state.combo=nil; state.shot_ready_since=nil; farm_release(scope,state); status("Waiting for current action"); return end
            local opponents,teammates=farm_opponents(model,state,mine.Position)
            local possession=held_ball(model)~=nil or model:GetAttribute("Basketball")==true
            local handler=Core.farm_holder(opponents,mine.Position,state.possession_owner)
            local teammate=Core.farm_holder(teammates,mine.Position,state.possession_owner)
            if handler then
                local action=handler.model:GetAttribute("Action")
