        end,interval=.05,conflicts={"guard","auto_shoot","fly","spin","auto_ankle","dribble_library","dribble_macros"}})
    for _,id in ipairs({"guard","auto_shoot","fly","spin","auto_ankle","dribble_library","dribble_macros"}) do
